import{_ as a,o as d,c as r,ag as e}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"format 格式化字符串","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/18. 字符串指令/format.md","filePath":"3. 指令/18. 字符串指令/format.md","lastUpdated":1778862643000}'),o={name:"3. 指令/18. 字符串指令/format.md"};function h(n,t,i,l,s,f){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="format-格式化字符串" tabindex="-1">format 格式化字符串 <a class="header-anchor" href="#format-格式化字符串" aria-label="Permalink to &quot;format 格式化字符串&quot;">​</a></h1><p>format 为格式化字符串指令，通过在参数 1 中传入合理的格式化控制符，其后带上任意多个参数来填充这个格式化控制符，并将填充后的数据返回。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>format(fmt, ...)</p><p>format(格式化字符串, 待填充参数...)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>fmt</td><td>string</td><td>字符串格式，含格式化控制符</td><td>—</td></tr><tr><td>...</td><td>string/real/int</td><td>待填充格式化控制符的参数，数量无限制</td><td>总长度不超过单个指令字符串长度</td></tr></tbody></table><p><strong>函数返回值</strong>：成功分割并保存到数组中的个数，int 型变量。</p><h3 id="格式化控制符说明" tabindex="-1">格式化控制符说明 <a class="header-anchor" href="#格式化控制符说明" aria-label="Permalink to &quot;格式化控制符说明&quot;">​</a></h3><p>格式化字符串以 <code>%</code> 开头，支持以下用法：</p><table tabindex="0"><thead><tr><th>格式符</th><th>说明</th></tr></thead><tbody><tr><td>%c</td><td>接受一个数字，并将其转化为 ASCII 码表中对应的字符</td></tr><tr><td>%d, %i</td><td>接受一个数字并将其转化为有符号的整数格式</td></tr><tr><td>%o</td><td>接受一个数字并将其转化为八进制数格式</td></tr><tr><td>%u</td><td>接受一个数字并将其转化为无符号整数格式</td></tr><tr><td>%x</td><td>接受一个数字并将其转化为十六进制数格式，使用小写字母</td></tr><tr><td>%X</td><td>接受一个数字并将其转化为十六进制数格式，使用大写字母</td></tr><tr><td>%f</td><td>接受一个数字并将其转化为浮点数格式</td></tr><tr><td>%s</td><td>接受一个字符串并按照给定的参数格式化该字符串</td></tr></tbody></table>',12)])])}const p=a(o,[["render",h]]);export{c as __pageData,p as default};
